        .warning-box { background: #2c2519; border: 1px solid var(--warning); color: var(--warning); padding: 10px; border-radius: 6px; font-size: 13px; margin-bottom: 15px; display: none; }
        .warning-box ul { padding-left: 20px; }

        .output-box { background: #0a0a0a; border: 1px solid var(--border); padding: 15px; border-radius: 6px; white-space: pre-wrap; font-family: monospace; font-size: 13px; max-height: 250px; overflow-y: auto; margin-bottom: 15px; }

        button { width: 100%; background: var(--accent); color: #000; border: none; padding: 12px; font-size: 15px; font-weight: bold; border-radius: 6px; cursor: pointer; margin-bottom: 10px; }
        button.secondary { background: #2d2d2d; color: #fff; border: 1px solid var(--border); }
    </style>
