        <button id="downloadBtn" class="secondary">Download Pack (.txt)</button>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            let selectedAngles = [];

            const angleTemplates = {
                hook: (name) => `🚨 DON'T THROW IT OUT: Turning yesterday's components into this ${name || '[Recipe Name]'}.`,
                problem: () => `Staring at containers wondering how to skip the exact same meal three days straight? We've all been there. Fridge fatigue is real, but waste is optional.`,
                process: (details) => `The play strategy here:\n${details || '[Enter recipe execution steps above]'}\nNothing complex, just smart rebuilding.`,
                cta: () => `Check your crisper drawer right now. What are you saving?`
            };

            const recipeNameInput = document.getElementById('recipeName');
            const recipeDetailsInput = document.getElementById('recipeDetails');
            const anglesContainer = document.getElementById('anglesContainer');
            const calloutsContainer = document.getElementById('calloutsContainer');
            const hashtagsContainer = document.getElementById('hashtagsContainer');
            const warningBox = document.getElementById('warningBox');
            const warningList = document.getElementById('warningList');
            const outputContent = document.getElementById('outputContent');
            const copyBtn = document.getElementById('copyBtn');
            const downloadBtn = document.getElementById('downloadBtn');

            function generatePack() {
                const name = recipeNameInput.value.trim();
                const details = recipeDetailsInput.value.trim();
                let captionParts = [];

                selectedAngles.forEach(angle => {
                    if (angleTemplates[angle]) {
                        captionParts.push(angleTemplates[angle](name, details));
                    }
                });

                let activeCallouts = [];
                calloutsContainer.querySelectorAll('.chip.active').forEach(chip => {
                    activeCallouts.push(chip.getAttribute('data-text'));
                });
                if (activeCallouts.length > 0) {
                    captionParts.push(activeCallouts.join('\n'));
                }

                let activeHashtags = [];
                hashtagsContainer.querySelectorAll('.chip.active').forEach(chip => {
                    activeHashtags.push(chip.getAttribute('data-tags'));
                });
                if (activeHashtags.length > 0) {
                    captionParts.push(activeHashtags.join(' '));
                }

                const finalEncoding = captionParts.join('\n\n');

                return {
                    text: finalEncoding,
                    name: name,
                    details: details,
                    angleCount: selectedAngles.length,
                    hashtagCount: activeHashtags.length
                };
            }

            function updateOutput() {
                const pack = generatePack();
                outputContent.textContent = pack.text || "Your built pack will compile here automatically...";
                checkWarnings(pack);
            }

            function checkWarnings(pack) {
                const currentWarnings = [];

                if (!pack.name) currentWarnings.push("Missing core leftover concept title.");
                if (!pack.details) currentWarnings.push("Recipe processing narrative/steps are empty.");
                if (pack.angleCount === 0) currentWarnings.push("No narrative structure angle selected. Tap the cards above to order your caption flow.");
                if (pack.hashtagCount === 0) currentWarnings.push("No hashtag grouping active. Discovery reach will be low.");
                if (pack.text.length > 2200) currentWarnings.push("Character ceiling risk: Pack content exceeds standard Instagram limit thresholds.");

                if (currentWarnings.length > 0) {
                    const fragment = document.createDocumentFragment();
                    currentWarnings.forEach(warningText => {
                        const li = document.createElement('li');
                        li.textContent = warningText;
                        fragment.appendChild(li);
                    });
                    warningList.replaceChildren(fragment);
                    warningBox.style.display = 'block';
                } else {
                    warningList.replaceChildren();
                    warningBox.style.display = 'none';
                }
            }

            function updateAngleNumbers() {
                anglesContainer.querySelectorAll('.angle-card').forEach(card => {
                    const angle = card.getAttribute('data-angle');
                    const index = selectedAngles.indexOf(angle);
                    const orderDiv = card.querySelector('.order');
                    orderDiv.textContent = index > -1 ? index + 1 : '';
                });
            }

            // Input Observers
            recipeNameInput.addEventListener('input', updateOutput);
            recipeDetailsInput.addEventListener('input', updateOutput);

            // Angle Card Selection Engine
            anglesContainer.addEventListener('click', (e) => {
                const card = e.target.closest('.angle-card');
                if (!card) return;

                const angle = card.getAttribute('data-angle');
                const index = selectedAngles.indexOf(angle);

                if (index > -1) {
                    selectedAngles.splice(index, 1);
                    card.classList.remove('selected');
                } else {
                    selectedAngles.push(angle);
                    card.classList.add('selected');
                }

                updateAngleNumbers();
                updateOutput();
            });

            // Unified Chip Selection Observers
            [calloutsContainer, hashtagsContainer].forEach(container => {
                container.addEventListener('click', (e) => {
                    const chip = e.target.closest('.chip');
                    if (!chip) return;
                    chip.classList.toggle('active');
                    updateOutput();
                });
            });

            // Action Workflows
            copyBtn.addEventListener('click', () => {
                const text = outputContent.textContent;
                navigator.clipboard.writeText(text);
            });

            downloadBtn.addEventListener('click', () => {
                const pack = generatePack();
                const text = pack.text;
                if (!text) return;

                const filename = (pack.name ? pack.name.toLowerCase().replace(/[^a-z0-9]+/g, '-') : 'recipe') + '-caption-pack.txt';
                const blob = new Blob([text], { type: 'text/plain' });
                const anchor = document.createElement('a');

                anchor.download = filename;
                anchor.href = window.URL.createObjectURL(blob);
                anchor.target = '_blank';
                anchor.style.display = 'none';
                document.body.appendChild(anchor);
                anchor.click();
                document.body.removeChild(anchor);
            });

            // Run initial compilation
            updateOutput();
        });
    </script>
</body>
</html>

